    starterCode: 'local LuaUtils = {}\n\nfunction LuaUtils:new()\n  local self = setmetatable({}, LuaUtils)\n  self.TableUtils = {}\n  self.StringUtils = {}\n  self.MathUtils = {}\n  return self\nend\n\n-- TableUtils: copy, merge, filter, map\n-- StringUtils: trim, split, format\n-- MathUtils: clamp, lerp, randomRange\n\nreturn LuaUtils',
    solution: 'local LuaUtils = {}\nLuaUtils.__index = LuaUtils\n\nfunction LuaUtils:new()\n  local self = setmetatable({}, LuaUtils)\n  \n  -- ============================================\n  -- TABLE UTILITIES\n  -- ============================================\n  self.TableUtils = {\n    -- Copia profunda de tabla\n    copy = function(original)\n      local copy = {}\n      for k, v in pairs(original) do\n        if type(v) == "table" then\n          copy[k] = self.TableUtils.copy(v)\n        else\n          copy[k] = v\n        end\n      end\n      return copy\n    end,\n    \n    -- Fusionar dos tablas\n    merge = function(t1, t2)\n      local result = {}\n      for k, v in pairs(t1) do result[k] = v end\n      for k, v in pairs(t2) do result[k] = v end\n      return result\n    end,\n    \n    -- Filtrar tabla\n    filter = function(t, predicate)\n      local result = {}\n      for k, v in pairs(t) do\n        if predicate(v, k) then\n          result[k] = v\n        end\n      end\n      return result\n    end,\n    \n    -- Mapear tabla\n    map = function(t, func)\n      local result = {}\n      for k, v in pairs(t) do\n        result[k] = func(v, k)\n      end\n      return result\n    end,\n    \n    -- Obtener keys de tabla\n    keys = function(t)\n      local result = {}\n      for k in pairs(t) do\n        table.insert(result, k)\n      end\n      return result\n    end,\n    \n    -- Obtener valores de tabla\n    values = function(t)\n      local result = {}\n      for _, v in pairs(t) do\n        table.insert(result, v)\n      end\n      return result\n    end\n  }\n  \n  -- ============================================\n  -- STRING UTILITIES\n  -- ============================================\n  self.StringUtils = {\n    -- Trim whitespace\n    trim = function(s)\n      return s:match("^%s*(.-)%s*$")\n    end,\n    \n    -- Split string\n    split = function(s, delimiter)\n      local result = {}\n      for part in s:gmatch("([^" .. delimiter .. "]+)") do\n        table.insert(result, part)\n      end\n      return result\n    end,\n    \n    -- Format string con argumentos\n    format = function(s, ...)\n      return string.format(s, ...)\n    end,\n    \n    -- Capitalizar primera letra\n    capitalize = function(s)\n      return s:sub(1, 1):upper() .. s:sub(2):lower()\n    end,\n    \n    -- Contar ocurrencias\n    count = function(s, pattern)\n      local count = 0\n      for _ in s:gmatch(pattern) do\n        count = count + 1\n      end\n      return count\n    end\n  }\n  \n  -- ============================================\n  -- MATH UTILITIES\n  -- ============================================\n  self.MathUtils = {\n    -- Clamp entre min y max\n    clamp = function(value, min, max)\n      return math.max(min, math.min(max, value))\n    end,\n    \n    -- Linear interpolation\n    lerp = function(a, b, t)\n      return a + (b - a) * t\n    end,\n    \n    -- Random en rango\n    randomRange = function(min, max)\n      return math.random() * (max - min) + min\n    end,\n    \n    -- Map de un rango a otro\n    map = function(value, inMin, inMax, outMin, outMax)\n      return (value - inMin) * (outMax - outMin) / (inMax - inMin) + outMin\n    end,\n    \n    -- Distancia entre dos puntos\n    distance = function(x1, y1, x2, y2)\n      return math.sqrt((x2 - x1)^2 + (y2 - y1)^2)\n    end,\n    \n    -- Angle entre dos puntos\n    angle = function(x1, y1, x2, y2)\n      return math.atan2(y2 - y1, x2 - x1)\n    end\n  }\n  \n  print("LuaUtils inicializado")\n  print("TableUtils: " .. #self.TableUtils .. " funciones")\n  print("StringUtils: " .. #self.StringUtils .. " funciones")\n  print("MathUtils: " .. #self.MathUtils .. " funciones")\n  \n  return self\nend\n\nreturn LuaUtils',
