    instructions: 'Crea un sistema de logging profesional para tus proyectos.\n\n**Requisitos:**\n- `Logger()` crea sistema de logging\n- `Log(message)` log normal\n- `Warn(message)` log de advertencia (amarillo)\n- `Error(message)` log de error (rojo)\n- `Debug(message)` log de debug (solo en debug mode)\n- `SetLevel(level)` setea nivel de logging\n\n**Pista:** Usa niveles de logging para filtrar mensajes',
    starterCode: 'local Logger = {}\n\nfunction Logger:new()\n  local self = setmetatable({}, Logger)\n  self.level = "DEBUG"\n  self.levels = { "DEBUG", "INFO", "WARN", "ERROR" }\n  return self\nend\n\nfunction Logger:Log(message)\n  -- Log normal\nend\n\nfunction Logger:Warn(message)\n  -- Log de advertencia\nend\n\nfunction Logger:Error(message)\n  -- Log de error\nend\n\nfunction Logger:Debug(message)\n  -- Log de debug\nend\n\nreturn Logger',
    solution: 'local Logger = {}\nLogger.__index = Logger\n\nfunction Logger:new()\n  local self = setmetatable({}, Logger)\n  self.level = "DEBUG"\n  self.levels = { DEBUG = 1, INFO = 2, WARN = 3, ERROR = 4 }\n  self.logHistory = {}\n  self.maxHistory = 100\n  print("Logger inicializado (nivel: " .. self.level .. ")")\n  return self\nend\n\nfunction Logger:_shouldLog(level)\n  return self.levels[level] >= self.levels[self.level]\nend\n\nfunction Logger:_formatMessage(level, message)\n  local timestamp = os.date("%H:%M:%S")\n  return string.format("[%s] [%s] %s", timestamp, level, message)\nend\n\nfunction Logger:Log(message, level)\n  level = level or "INFO"\n  \n  if not self:_shouldLog(level) then\n    return\n  end\n  \n  local formatted = self:_formatMessage(level, message)\n  \n  -- Guardar en historial\n  table.insert(self.logHistory, {\n    level = level,\n    message = message,\n    formatted = formatted,\n    time = os.time()\n  })\n  \n  -- Limitar historial\n  if #self.logHistory > self.maxHistory then\n    table.remove(self.logHistory, 1)\n  end\n  \n  -- Imprimir con color según nivel\n  if level == "ERROR" then\n    print("❌ " .. formatted)\n  elseif level == "WARN" then\n    print("⚠️ " .. formatted)\n  elseif level == "DEBUG" then\n    print("🔍 " .. formatted)\n  else\n    print("✓ " .. formatted)\n  end\nend\n\nfunction Logger:Info(message)\n  self:Log(message, "INFO")\nend\n\nfunction Logger:Warn(message)\n  self:Log(message, "WARN")\nend\n\nfunction Logger:Error(message)\n  self:Log(message, "ERROR")\nend\n\nfunction Logger:Debug(message)\n  self:Log(message, "DEBUG")\nend\n\nfunction Logger:SetLevel(level)\n  if not self.levels[level] then\n    print("Nivel inválido: " .. level)\n    return false\n  end\n  \n  self.level = level\n  print("Nivel de logging cambiado a: " .. level)\n  return true\nend\n\nfunction Logger:GetHistory()\n  return self.logHistory\nend\n\nfunction Logger:ClearHistory()\n  self.logHistory = {}\n  print("Historial de logs limpiado")\nend\n\nfunction Logger:SaveToFile(filename)\n  print("Guardando logs en: " .. filename)\n  \n  local file = io.open(filename, "w")\n  if file then\n    for _, log in ipairs(self.logHistory) do\n      file:write(log.formatted .. "\\n")\n    end\n    file:close()\n    print("Logs guardados exitosamente")\n    return true\n  end\n  \n  print("Error al guardar logs")\n  return false\nend\n\n-- Logger global de conveniencia\nlocal globalLogger = Logger:new()\n\nreturn {\n  Logger = Logger,\n  Log = function(msg) globalLogger:Log(msg) end,\n  Info = function(msg) globalLogger:Info(msg) end,\n  Warn = function(msg) globalLogger:Warn(msg) end,\n  Error = function(msg) globalLogger:Error(msg) end,\n  Debug = function(msg) globalLogger:Debug(msg) end,\n  SetLevel = function(level) globalLogger:SetLevel(level) end\n}',
