    instructions: 'Crea un sistema para cargar y guardar configuración del juego.\n\n**Requisitos:**\n- `ConfigManager()` crea manager de configuración\n- `Load(path)` carga configuración desde archivo\n- `Save(path)` guarda configuración en archivo\n- `Get(key)` obtiene valor de configuración\n- `Set(key, value)` setea valor de configuración\n- Soporta nested configs (ej: "graphics.resolution")\n\n**Pista:** Usa tablas anidadas para configuración',
    starterCode: 'local ConfigManager = {}\n\nfunction ConfigManager:new()\n  local self = setmetatable({}, ConfigManager)\n  self.config = {}\n  self.path = nil\n  return self\nend\n\nfunction ConfigManager:Load(path)\n  -- Carga configuración\nend\n\nfunction ConfigManager:Save(path)\n  -- Guarda configuración\nend\n\nfunction ConfigManager:Get(key)\n  -- Obtiene valor\nend\n\nfunction ConfigManager:Set(key, value)\n  -- Setea valor\nend\n\nreturn ConfigManager',
    solution: 'local ConfigManager = {}\nConfigManager.__index = ConfigManager\n\nfunction ConfigManager:new()\n  local self = setmetatable({}, ConfigManager)\n  self.config = {}\n  self.path = nil\n  print("ConfigManager inicializado")\n  return self\nend\n\nfunction ConfigManager:Load(path)\n  print("Cargando configuración: " .. path)\n  self.path = path\n  \n  -- Configuración por defecto\n  self.config = {\n    graphics = {\n      resolution = "1920x1080",\n      fullscreen = true,\n      vsync = true,\n      quality = "High"\n    },\n    audio = {\n      masterVolume = 0.8,\n      musicVolume = 0.6,\n      sfxVolume = 0.7,\n      muted = false\n    },\n    gameplay = {\n      difficulty = "Normal",\n      subtitles = true,\n      autoSave = true\n    },\n    controls = {\n      keybinds = {\n        move_forward = "W",\n        move_back = "S",\n        move_left = "A",\n        move_right = "D",\n        interact = "E",\n        jump = "SPACE"\n      },\n      mouseSensitivity = 1.0\n    }\n  }\n  \n  print("Configuración cargada exitosamente")\n  self:PrintConfig()\n  \n  return self.config\nend\n\nfunction ConfigManager:Save(path)\n  local savePath = path or self.path\n  \n  if not savePath then\n    print("Error: No hay path para guardar")\n    return false\n  end\n  \n  print("Guardando configuración: " .. savePath)\n  \n  -- En implementación real: escribir a archivo\n  -- local file = io.open(savePath, "w")\n  -- file:write(json.encode(self.config))\n  -- file:close()\n  \n  print("Configuración guardada exitosamente")\n  return true\nend\n\nfunction ConfigManager:Get(key)\n  -- Soportar keys anidadas: "graphics.resolution"\n  local keys = {}\n  for part in key:gmatch("[^.]+") do\n    table.insert(keys, part)\n  end\n  \n  local current = self.config\n  for _, k in ipairs(keys) do\n    if type(current) ~= "table" then\n      return nil\n    end\n    current = current[k]\n  end\n  \n  return current\nend\n\nfunction ConfigManager:Set(key, value)\n  local keys = {}\n  for part in key:gmatch("[^.]+") do\n    table.insert(keys, part)\n  end\n  \n  local current = self.config\n  for i = 1, #keys - 1 do\n    if not current[keys[i]] then\n      current[keys[i]] = {}\n    end\n    current = current[keys[i]]\n  end\n  \n  current[keys[#keys]] = value\n  print("Configuración actualizada: " .. key .. " = " .. tostring(value))\n  \n  return true\nend\n\nfunction ConfigManager:PrintConfig()\n  print("\\n=== CONFIGURACIÓN ===")\n  \n  for section, values in pairs(self.config) do\n    print("\\n[" .. section .. "]")\n    for key, value in pairs(values) do\n      if type(value) == "table" then\n        for k, v in pairs(value) do\n          print("  " .. k .. ": " .. tostring(v))\n        end\n      else\n        print("  " .. key .. ": " .. tostring(value))\n      end\n    end\n  end\n  \n  print("====================\\n")\nend\n\nfunction ConfigManager:ResetToDefaults()\n  print("Reseteando configuración a valores por defecto")\n  self:Load(self.path)\nend\n\nfunction ConfigManager:GetAll()\n  return self.config\nend\n\nreturn ConfigManager',
