    starterCode: 'local NetworkingPlanner = {}\n\nfunction NetworkingPlanner:new()\n  local self = setmetatable({}, NetworkingPlanner)\n  self.contacts = {}\n  self.events = {}\n  self.goals = {}\n  return self\nend\n\nfunction NetworkingPlanner:AddContact(name, role, company, contact)\n  -- Añade contacto\nend\n\nfunction NetworkingPlanner:AddEvent(name, date, type)\n  -- Añade evento\nend\n\nfunction NetworkingPlanner:SetGoals(goals)\n  -- Setea metas\nend\n\nfunction NetworkingPlanner:GenerateReport()\n  -- Genera reporte\nend\n\nreturn NetworkingPlanner',
    solution: 'local NetworkingPlanner = {}\nNetworkingPlanner.__index = NetworkingPlanner\n\nfunction NetworkingPlanner:new()\n  local self = setmetatable({}, NetworkingPlanner)\n  self.contacts = {}\n  self.events = {}\n  self.goals = {}\n  self.followUps = {}\n  print("NetworkingPlanner inicializado")\n  return self\nend\n\nfunction NetworkingPlanner:AddContact(name, role, company, contact)\n  local newContact = {\n    id = #self.contacts + 1,\n    name = name,\n    role = role,\n    company = company,\n    contact = contact,\n    dateAdded = os.date("%Y-%m-%d"),\n    lastContact = nil,\n    notes = ""\n  }\n  \n  table.insert(self.contacts, newContact)\n  print("Contacto añadido: " .. name .. " (" .. role .. " en " .. company .. ")")\n  return newContact\nend\n\nfunction NetworkingPlanner:AddEvent(name, date, eventType)\n  local newEvent = {\n    id = #self.events + 1,\n    name = name,\n    date = date,\n    type = eventType, -- "Conference", "Meetup", "Online", "Workshop"\n    attended = false,\n    contactsMet = {}\n  }\n  \n  table.insert(self.events, newEvent)\n  print("Evento añadido: " .. name .. " (" .. date .. ")")\n  return newEvent\nend\n\nfunction NetworkingPlanner:SetGoals(goals)\n  -- goals: { contactsPerMonth, eventsPerMonth, followUpRate }\n  self.goals = goals\n  print("Metas de networking establecidas")\nend\n\nfunction NetworkingPlanner:AddFollowUp(contactId, task, dueDate)\n  table.insert(self.followUps, {\n    contactId = contactId,\n    task = task,\n    dueDate = dueDate,\n    completed = false\n  })\n  print("Follow-up añadido para contacto #" .. contactId)\nend\n\nfunction NetworkingPlanner:GenerateReport()\n  local report = "\\n=== REPORTE DE NETWORKING ===\\n\\n"\n  \n  -- Contactos\n  report = report .. "📇 Contactos: " .. #self.contacts .. "\\n"\n  \n  if #self.contacts > 0 then\n    report = report .. "\\nContactos por empresa:\\n"\n    local companyCount = {}\n    for _, contact in ipairs(self.contacts) do\n      companyCount[contact.company] = (companyCount[contact.company] or 0) + 1\n    end\n    \n    for company, count in pairs(companyCount) do\n      report = report .. "  • " .. company .. ": " .. count .. "\\n"\n    end\n  end\n  \n  -- Eventos\n  report = report .. "\\n📅 Eventos: " .. #self.events .. "\\n"\n  \n  local attended = 0\n  for _, event in ipairs(self.events) do\n    if event.attended then attended = attended + 1 end\n  end\n  report = report .. "  Asistidos: " .. attended .. "/" .. #self.events .. "\\n"\n  \n  -- Follow-ups\n  report = report .. "\\n✅ Follow-ups pendientes: " .. #self.followUps .. "\\n"\n  \n  -- Metas\n  if self.goals.contactsPerMonth then\n    report = report .. "\\n🎯 Metas:\\n"\n    report = report .. "  • Contactos/mes: " .. (self.goals.contactsPerMonth or "N/A") .. "\\n"\n    report = report .. "  • Eventos/mes: " .. (self.goals.eventsPerMonth or "N/A") .. "\\n"\n  end\n  \n  -- Consejos\n  report = report .. "\\n💡 Consejos:\\n"\n  report = report .. "  • Sigue en contacto regularmente\\n"\n  report = report .. "  • Ofrece ayuda antes de pedir\\n"\n  report = report .. "  • Asiste a eventos de la industria\\n"\n  report = report .. "  • Mantén tu LinkedIn actualizado\\n"\n  \n  report = report .. "\\n==============================\\n"\n  \n  print(report)\n  return report\nend\n\nfunction NetworkingPlanner:GetContactCount()\n  return #self.contacts\nend\n\nfunction NetworkingPlanner:GetEventCount()\n  return #self.events\nend\n\nfunction NetworkingPlanner:ExportContacts()\n  local csv = "Name,Role,Company,Contact,Date Added\\n"\n  \n  for _, contact in ipairs(self.contacts) do\n    csv = csv .. contact.name .. "," .. contact.role .. "," .. contact.company .. "," .. contact.contact .. "," .. contact.dateAdded .. "\\n"\n  end\n  \n  return csv\nend\n\nreturn NetworkingPlanner',
